import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年9月8日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-08.md","filePath":"science-log/src/reconstructed/2026-09-08.md"}'),n={name:"science-log/src/reconstructed/2026-09-08.md"};function s(i,e,l,h,c,g){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年9月8日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月8日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月8日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月8日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日为周二（2026-09-08），Nature（0028-0836）CrossRef 命中 15 条全为 <code>d41586</code> 新闻/Briefing 与 1 条 Author Correction、<strong>无 <code>s41586</code> 研究论文</strong>；Science 系（10.1126）11 条多为新闻稿，研究性条目来自 Science Signaling。故科学 5 篇中 4 篇取自当日 PNAS（0027-8424）研究论文，1 篇取自 Science Signaling。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202609080000 TO 202609082359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="⚛️-压缩光探测增强的相干拉曼光谱" tabindex="-1">⚛️ 压缩光探测增强的相干拉曼光谱 <a class="header-anchor" href="#⚛️-压缩光探测增强的相干拉曼光谱" aria-label="Permalink to &quot;⚛️ 压缩光探测增强的相干拉曼光谱&quot;">​</a></h3><p><strong>Quantum-enhanced coherent Raman spectroscopy with broadband squeezed-light detection</strong><em>PNAS (2026)</em></p><p>相干拉曼散射（CRS）显微术能在无标记条件下读取分子振动指纹，但信号弱、易被散粒噪声限制，长期依赖提高激光功率（会损伤样品）。本研究由加州大学欧文分校 Konstantin E. Dorfman、德克萨斯 A&amp;M 大学 Vladislav V. Yakovlev 与加州大学尔湾分校 Shaul Mukamel 合作，提出用<strong>宽带压缩光</strong>做探测端。相干拉曼过程把量子噪声从探测光转移到分子振动模式上，作者据此设计量子增强探测方案，理论上可在保持低光剂量的同时压低探测噪声，为活细胞与材料的低损伤高灵敏振动成像提供新路径。DOI: <a href="https://doi.org/10.1073/pnas.2611941123" target="_blank" rel="noreferrer">10.1073/pnas.2611941123</a></p><h3 id="🦶-足跟着地力学揭示人科双足行走的演化权衡" tabindex="-1">🦶 足跟着地力学揭示人科双足行走的演化权衡 <a class="header-anchor" href="#🦶-足跟着地力学揭示人科双足行走的演化权衡" aria-label="Permalink to &quot;🦶 足跟着地力学揭示人科双足行走的演化权衡&quot;">​</a></h3><p><strong>Heel-strike mechanics reveal evolutionary trade-offs in hominin bipedalism</strong><em>PNAS (2026)</em></p><p>人类之所以能直立行走，与足跟先着地（heel-strike）这一独特步态密切相关，但其力学代价一直未被定量刻画。哈佛大学 Nicholas B. Holowka 团队通过受力测量与运动学分析，比较足跟着地与其他着地方式在冲击吸收、能量效率与关节负荷上的差异，揭示足跟着地在获得稳定与效率的同时，带来了特有的力学负担——这是一项<strong>演化权衡</strong>而非单向优化。工作为理解人科双足步态的起源与相关损伤（如足底筋膜炎、应力性骨折）提供了力学基础。DOI: <a href="https://doi.org/10.1073/pnas.2533918123" target="_blank" rel="noreferrer">10.1073/pnas.2533918123</a></p><h3 id="🧬-体内全基因组-crispr-筛选锁定-foxr1-为-cd8-t-细胞抗肿瘤免疫的抑制因子" tabindex="-1">🧬 体内全基因组 CRISPR 筛选锁定 FOXR1 为 CD8⁺ T 细胞抗肿瘤免疫的抑制因子 <a class="header-anchor" href="#🧬-体内全基因组-crispr-筛选锁定-foxr1-为-cd8-t-细胞抗肿瘤免疫的抑制因子" aria-label="Permalink to &quot;🧬 体内全基因组 CRISPR 筛选锁定 FOXR1 为 CD8⁺ T 细胞抗肿瘤免疫的抑制因子&quot;">​</a></h3><p><strong>In vivo genome-wide CRISPR screens identify FOXR1 as a suppressor of CD8⁺ T cell antitumor immunity</strong><em>PNAS (2026)</em></p><p>CD8⁺ T 细胞是抗肿瘤免疫的主力，但肿瘤微环境会通过多种通路抑制其功能。Xue Yang 等以体内全基因组 CRISPR 筛选系统性寻找限制 T 细胞抗肿瘤活性的基因，鉴定出转录因子 FOXR1 为负调控因子：敲除 FOXR1 可增强 CD8⁺ T 细胞的杀伤与浸润能力。该发现给出了一个可药物化的免疫治疗新靶点，也说明&quot;体内筛选&quot;比体外更能还原真实免疫压力下的调控网络。DOI: <a href="https://doi.org/10.1073/pnas.2534362123" target="_blank" rel="noreferrer">10.1073/pnas.2534362123</a></p><h3 id="🧠-尺寸定制纳米颗粒—抗体偶联物克服肝脏截留-改善阿尔茨海默病治疗" tabindex="-1">🧠 尺寸定制纳米颗粒—抗体偶联物克服肝脏截留，改善阿尔茨海默病治疗 <a class="header-anchor" href="#🧠-尺寸定制纳米颗粒—抗体偶联物克服肝脏截留-改善阿尔茨海默病治疗" aria-label="Permalink to &quot;🧠 尺寸定制纳米颗粒—抗体偶联物克服肝脏截留，改善阿尔茨海默病治疗&quot;">​</a></h3><p><strong>Size-tailored nanoparticle–antibody conjugates overcome hepatic sequestration in Alzheimer&#39;s disease treatment</strong><em>PNAS (2026)</em></p><p>抗体药物入脑后剂量不足，一大原因是会被肝脏快速截留（hepatic sequestration），导致脑内暴露量低。华中科技大学 Haiming Luo 团队通过<strong>调控纳米颗粒—抗体偶联物的尺寸</strong>来改变其体内分布，减少肝脏摄取、提高脑靶向递送效率，从而在阿尔茨海默病模型中改善治疗性抗体的脑内作用。研究把&quot;递送工程&quot;作为抗体疗法增效的关键变量，对中枢神经系统大分子药物普遍适用。DOI: <a href="https://doi.org/10.1073/pnas.2603034123" target="_blank" rel="noreferrer">10.1073/pnas.2603034123</a></p><h3 id="🎯-hras-以密码子与等位基因特异性促进突变-nras-驱动的细胞转化" tabindex="-1">🎯 HRAS 以密码子与等位基因特异性促进突变 NRAS 驱动的细胞转化 <a class="header-anchor" href="#🎯-hras-以密码子与等位基因特异性促进突变-nras-驱动的细胞转化" aria-label="Permalink to &quot;🎯 HRAS 以密码子与等位基因特异性促进突变 NRAS 驱动的细胞转化&quot;">​</a></h3><p><strong>HRAS promotes mutant NRAS–driven transformation with codon and allele specificity</strong><em>Science Signaling (2026)</em></p><p>RAS 家族（HRAS / KRAS / NRAS）突变是人类癌症最常见的驱动事件，但不同 RAS 异构体之间的关系尚不清楚。Hyun Lee 等发现，野生型 HRAS 能促进突变 NRAS 驱动的细胞转化，且这种促进作用<strong>依赖具体的突变密码子与等位基因</strong>——同一基因的不同突变位点对 HRAS 的需求不同。这揭示了 RAS 异构体之间此前被忽略的协同，也解释了为何不同 RAS 突变型肿瘤对通路抑制剂的响应存在差异。DOI: <a href="https://doi.org/10.1126/scisignal.aej6209" target="_blank" rel="noreferrer">10.1126/scisignal.aej6209</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧪-harness-还是模型-用污染可控的私有套件隔离智能体编码中的框架效应" tabindex="-1">🧪 Harness 还是模型？用污染可控的私有套件隔离智能体编码中的框架效应 <a class="header-anchor" href="#🧪-harness-还是模型-用污染可控的私有套件隔离智能体编码中的框架效应" aria-label="Permalink to &quot;🧪 Harness 还是模型？用污染可控的私有套件隔离智能体编码中的框架效应&quot;">​</a></h3><p><strong>Harness or Model? Isolating the Harness Effect in Agentic Coding with a Contamination-Controlled Private Suite</strong><em>arXiv (2026)</em></p><p>编码智能体的成绩取决于两件事：底层模型的推理能力，以及外层&quot;框架&quot;（harness：提示模板、工具接口、循环控制）的设计。两者长期混淆，且公开基准易被训练数据污染。作者构建了一套<strong>污染可控的私有评测套件</strong>，把 harness 变量单独隔离出来做对照实验，从而区分&quot;模型变强&quot;与&quot;框架变好&quot;各贡献多少。它把智能体工程从经验调参推向可测量的因果分析。arXiv: <a href="https://arxiv.org/abs/2609.11987" target="_blank" rel="noreferrer">2609.11987</a></p><h3 id="🎯-智能体知道自己成功了吗-从内部表征校准智能体置信度" tabindex="-1">🎯 智能体知道自己成功了吗？从内部表征校准智能体置信度 <a class="header-anchor" href="#🎯-智能体知道自己成功了吗-从内部表征校准智能体置信度" aria-label="Permalink to &quot;🎯 智能体知道自己成功了吗？从内部表征校准智能体置信度&quot;">​</a></h3><p><strong>Do Agents Know When They Succeed? Calibrating Agent Confidence from Internal Representations</strong><em>arXiv (2026)</em></p><p>智能体在长程任务中常常&quot;不知道自己已经失败&quot;，导致无谓的重复尝试与算力浪费。作者不去读它的输出文本，而是直接从<strong>模型内部表征</strong>中解码出&quot;当前成功的置信度&quot;，并据此校准自我评估。结果显示内部状态比事后自然语言自陈更可靠地反映真实成败。这为智能体自停、早退与资源调度提供了廉价而有效的信号。arXiv: <a href="https://arxiv.org/abs/2609.09448" target="_blank" rel="noreferrer">2609.09448</a></p><h3 id="🛡️-多模态提示注入攻击对智能体框架的实证评估" tabindex="-1">🛡️ 多模态提示注入攻击对智能体框架的实证评估 <a class="header-anchor" href="#🛡️-多模态提示注入攻击对智能体框架的实证评估" aria-label="Permalink to &quot;🛡️ 多模态提示注入攻击对智能体框架的实证评估&quot;">​</a></h3><p><strong>An Experimental Evaluation of Multimodal Prompt Injection Attacks on Agentic AI Frameworks</strong><em>arXiv (2026)</em></p><p>当智能体能读网页、看图片、调用工具时，攻击面就从文本扩展到图像与界面。本文系统评测了<strong>多模态提示注入</strong>（把恶意指令藏进图像或跨模态内容）对主流智能体框架的攻击成功率，比较不同模态、编码方式与防护策略的效果。它把&quot;智能体安全&quot;从单一文本注入，推进到多模态与工具链的真实威胁模型，为防御设计提供基线数据。arXiv: <a href="https://arxiv.org/abs/2609.09404" target="_blank" rel="noreferrer">2609.09404</a></p><h3 id="🤖-tango-用全身视觉—语言—动作模型实现人形机器人在杂乱环境中导航" tabindex="-1">🤖 TANGO：用全身视觉—语言—动作模型实现人形机器人在杂乱环境中导航 <a class="header-anchor" href="#🤖-tango-用全身视觉—语言—动作模型实现人形机器人在杂乱环境中导航" aria-label="Permalink to &quot;🤖 TANGO：用全身视觉—语言—动作模型实现人形机器人在杂乱环境中导航&quot;">​</a></h3><p><strong>TANGO: Humanoid Navigation in Cluttered Environments with a Whole-Body Vision-Language-Action Model</strong><em>arXiv (2026)</em></p><p>人形机器人在杂乱空间导航时，既要理解语言指令与视觉场景，又要协调全身关节避免碰撞。TANGO 把视觉—语言—动作（VLA）建模扩展到<strong>全身控制</strong>，让高层语义理解与低层全身运动在同一框架中耦合，从而在狭小、动态的环境中完成导航。它代表了&quot;具身智能&quot;从轮式/机械臂向高自由度人形本体推进的一步。arXiv: <a href="https://arxiv.org/abs/2609.09158" target="_blank" rel="noreferrer">2609.09158</a></p><h3 id="🧠-微分功能主义-雅可比矩阵塑造现象经验的结构" tabindex="-1">🧠 微分功能主义：雅可比矩阵塑造现象经验的结构 <a class="header-anchor" href="#🧠-微分功能主义-雅可比矩阵塑造现象经验的结构" aria-label="Permalink to &quot;🧠 微分功能主义：雅可比矩阵塑造现象经验的结构&quot;">​</a></h3><p><strong>Differential Functionalism: Jacobians Shape the Structure of Phenomenal Experience</strong><em>arXiv (2026)</em></p><p>功能主义认为&quot;经验&quot;由系统实现的功能决定，但难以说明经验为何具有连续、可分解的几何结构。本文提出<strong>微分功能主义</strong>：用系统的雅可比矩阵（输入—输出局部灵敏度的线性化）来刻画&quot;功能结构&quot;，并论证正是这种可微结构塑造了现象经验的组织方式。它把意识研究的哲学争论与动力系统/可微计算的语言对接，给出一个可计算、可检验的框架。arXiv: <a href="https://arxiv.org/abs/2609.09306" target="_blank" rel="noreferrer">2609.09306</a></p><blockquote><p>📅 日期：2026-09-08 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 期号：（第 ? 期 · 事后重建版）</p></blockquote>',35)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
